// Builds the import plan of the FAKE fixture and embeds it in
// supabase/tests/import.sql (between the PLAN markers), so the SQL test
// imports exactly what the app would send. Run: npm run test:fixtures
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { CRM_2026, proposeMapping } from "../../src/lib/import/presets";
import { buildPlan, type PlanRow } from "../../src/lib/import/transform";
import { readXlsx } from "../../src/lib/import/workbook";

// Car park created by the SQL test with this fixed id.
export const TEST_PARKING_ID = "00000000-0000-4000-8000-0000000000f1";

const ROOT = join(__dirname, "..", "..", "..");
export const FIXTURE = join(ROOT, "tests", "fixtures", "crm-parcheggio-2026-finto.xlsx");
export const SQL_TEST = join(ROOT, "supabase", "tests", "import.sql");
const BEGIN = "-- BEGIN PLAN (generated by tests/fixtures/build-import-plan.ts)";
const END = "-- END PLAN";

export async function fixturePlan(): Promise<PlanRow[]> {
  const buffer = readFileSync(FIXTURE);
  const { sheets } = await readXlsx(buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength));
  // Sheets that do not follow the preset ("Mail Template", "Tabella Tariffe") are left out.
  return buildPlan(
    sheets.flatMap((sheet) => {
      const mapping = proposeMapping(CRM_2026, sheet);
      return mapping ? [{ name: sheet.name, rows: sheet.rows, mapping, parkingId: TEST_PARKING_ID }] : [];
    }),
  );
}

export function planBlock(plan: PlanRow[]): string {
  const json = JSON.stringify(plan, null, 1).replace(/\$plan\$/g, "");
  return `${BEGIN}\ninsert into plan_input values ($plan$${json}$plan$::jsonb);\n${END}`;
}

export function embeddedBlock(sql: string): string {
  const start = sql.indexOf(BEGIN);
  const end = sql.indexOf(END);
  return start >= 0 && end > start ? sql.slice(start, end + END.length) : "";
}

if (require.main === module) {
  fixturePlan().then((plan) => {
    const sql = readFileSync(SQL_TEST, "utf8");
    const current = embeddedBlock(sql);
    if (!current) throw new Error("PLAN markers not found in supabase/tests/import.sql");
    writeFileSync(SQL_TEST, sql.replace(current, planBlock(plan)));
    console.log(`Piano di ${plan.length} righe scritto in supabase/tests/import.sql`);
  });
}
